#include <iostream>
#include <vector>
#include <algorithm>

void print_vec(const std::vector<int>& v) {
    for (int x : v) {
        std::cout << x << " ";
    }
    std::cout << "\n";
}

int main() {
    std::vector<int> v = {3, 100, 52, 77, 22};

    std::cout << "is_heap initially: " << std::boolalpha << std::is_heap(v.begin(), v.end()) << "\n";

    std::make_heap(v.begin(), v.end());
    std::cout << "After make_heap: ";
    print_vec(v);
    std::cout << "is_heap after make_heap: " << std::is_heap(v.begin(), v.end()) << "\n";

    // Push a new element
    v.push_back(98);
    std::push_heap(v.begin(), v.end());
    std::cout << "After push_heap(98): ";
    print_vec(v);

    // Pop maximum element
    std::pop_heap(v.begin(), v.end());
    std::cout << "Popped element moved to back: " << v.back() << "\n";
    v.pop_back();
    std::cout << "After pop_back: ";
    print_vec(v);

    // Sort heap
    std::sort_heap(v.begin(), v.end());
    std::cout << "After sort_heap: ";
    print_vec(v);

    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>

int main() {
    // min and max with two arguments
    std::cout << "min(12, 7): " << std::min(12, 7) << "\n";
    std::cout << "max(12, 7): " << std::max(12, 7) << "\n";

    // min and max with initializer_list (C++11)
    int list_min = std::min({10, 7, 14, 21, 17});
    int list_max = std::max({10, 7, 14, 21, 17});
    std::cout << "list_min: " << list_min << ", list_max: " << list_max << "\n";

    // minmax with two arguments
    auto p1 = std::minmax(12, 7);
    std::cout << "minmax(12, 7): first=" << p1.first << ", second=" << p1.second << "\n";

    // minmax_element on container range with C++17 structured binding
    std::vector<int> items = {3, 100, 52, 77, 22, 31, 1, 98, 13, 40};
    auto [min_it, max_it] = std::minmax_element(items.begin(), items.end());
    std::cout << "min element: " << *min_it << " at index " << (min_it - items.begin()) << "\n";
    std::cout << "max element: " << *max_it << " at index " << (max_it - items.begin()) << "\n";

    return 0;
}
